package abstraction_interfaces.assigment_problems;

import java.util.*;public class CollegeFeeCounter {interface Student{String name();double fee();}static class DayScholar implements Student{String n;DayScholar(String n){this.n=n;}public String name(){return n;}public double fee(){return 52000;}}static class Hosteller implements Student{String n;Hosteller(String n){this.n=n;}public String name(){return n;}public double fee(){return 100000;}}static class Scholar implements Student{String n;Scholar(String n){this.n=n;}public String name(){return n;}public double fee(){return 32000;}}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next(),name=s.next();Student p=t.equals("DAY_SCHOLAR")?new DayScholar(name):t.equals("HOSTELLER")?new Hosteller(name):new Scholar(name);System.out.printf(Locale.US,"%s: %.2f%n",p.name(),p.fee());total+=p.fee();}System.out.printf(Locale.US,"Total Collected: %.2f%n",total);}}
